from collections import Counter

def transform(grid):
    n = len(grid) // 3
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            block = [
                grid[i][j]
                for i in range(3*r, 3*r+3)
                for j in range(3*c, 3*c+3)
            ]
            counts = Counter(block)
            row.append(max(counts, key=lambda color: (counts[color], -color)))
        out.append(row)
    return out
